function getModelCategory({ provider, model }) {
  if (provider === PROVIDERS.VERCEL_AI_GATEWAY) return PREMIUM_OSS_MODEL_SET.has(model) ? "premium" : "opensource";
  if (provider === PROVIDERS.CLOUDFLARE_AI_GATEWAY || provider === PROVIDERS.OPENROUTER)
    return "opensource";
  const providerPricing = PRICING_TABLE[provider];
  if (!providerPricing) return null;
  const fullModelId = `${provider}:${model}`,
    entry = providerPricing.find((e) => e.id === fullModelId);
  return entry?.category ?? null;
}
function getPlanDisplayName(planId) {
  return planId
    .replace("individual-", "")
    .replace("teams-", "Teams ")
    .split(" ")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}
function getMinimumPlanForModel({ fullModelId, category }) {
  for (const planId of PLAN_ORDER) {
    const restrictions = PLAN_RESTRICTIONS[planId];
    if (!restrictions) continue;
    const categoryAllowed = restrictions.allowedCategories.includes(category),
      isBlocked = restrictions.blockedModels?.includes(fullModelId) ?? false;
    if (categoryAllowed && !isBlocked) return planId;
  }
  return null;
}
